//! Localization: every `assets/i18n/<locale>/*.ftl` file is embedded at build time (see
//! `build.rs`), the locale is the settings override or the OS UI language, and `en` is the
//! fallback (spec §0).

use ssw_core::i18n::Localizer;

/// The embedded assets generated by `build.rs`.
pub mod embedded {
    include!(concat!(env!("OUT_DIR"), "/embedded_assets.rs"));
}

/// The locale to use: the settings override when it is a non-empty tag, else the OS UI
/// language.
#[must_use]
pub fn resolve_locale(settings_language: Option<&str>, os_language: &str) -> String {
    settings_language
        .map(str::trim)
        .filter(|tag| !tag.is_empty())
        .unwrap_or(os_language)
        .to_owned()
}

/// A [`Localizer`] over every embedded Fluent file, with the fallback chain
/// `locale` → language → `en`.
#[must_use]
pub fn localizer_for(locale: &str) -> Localizer {
    let sources: Vec<(&str, &str)> = embedded::FTL_FILES
        .iter()
        .map(|(source_locale, _, source)| (*source_locale, *source))
        .collect();
    Localizer::new(locale, &sources)
}

/// The welcome document for `locale` (`Welcome.md` in `Documents\SS Writer\`): the exact
/// locale, then its language, then `en`.
#[must_use]
pub fn welcome_text(locale: &str) -> &'static str {
    let normalized = locale.trim().replace('_', "-");
    let language = normalized.split('-').next().unwrap_or_default();
    [normalized.as_str(), language, "en"]
        .iter()
        .find_map(|wanted| {
            embedded::WELCOME_FILES
                .iter()
                .find(|(name, _)| name.eq_ignore_ascii_case(wanted))
                .map(|(_, text)| *text)
        })
        .unwrap_or_default()
}

#[cfg(test)]
mod tests {
    use std::collections::BTreeSet;
    use std::path::PathBuf;

    use ssw_core::command::{CommandGroup, CommandId};

    use super::*;

    fn assets_dir() -> PathBuf {
        PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("..")
            .join("..")
            .join("assets")
    }

    #[test]
    fn every_ftl_file_on_disk_is_embedded() {
        let mut on_disk = BTreeSet::new();
        for locale in std::fs::read_dir(assets_dir().join("i18n")).unwrap() {
            let locale = locale.unwrap().path();
            let files = std::fs::read_dir(&locale)
                .unwrap()
                .map(|file| file.unwrap().path());
            for file in files.filter(|file| file.extension().is_some_and(|ext| ext == "ftl")) {
                on_disk.insert((
                    locale.file_name().unwrap().to_string_lossy().into_owned(),
                    file.file_name().unwrap().to_string_lossy().into_owned(),
                    std::fs::read_to_string(&file).unwrap(),
                ));
            }
        }
        let embedded: BTreeSet<_> = embedded::FTL_FILES
            .iter()
            .map(|(locale, name, source)| {
                (
                    (*locale).to_owned(),
                    (*name).to_owned(),
                    (*source).to_owned(),
                )
            })
            .collect();
        assert!(on_disk.iter().any(|(_, name, _)| name == "app.ftl"));
        assert!(on_disk.iter().any(|(_, name, _)| name == "main.ftl"));
        assert_eq!(embedded, on_disk);
    }

    #[test]
    fn every_embedded_file_parses_cleanly() {
        let localizer = localizer_for("en");
        assert_eq!(localizer.diagnostics(), &[] as &[String]);
        assert_eq!(localizer.loaded_locales(), ["en"]);
    }

    #[test]
    fn every_command_and_group_label_exists_in_english() {
        let localizer = localizer_for("en");
        let labels: Vec<&str> = CommandId::all().map(CommandId::label_id).collect();
        let missing: Vec<&&str> = labels
            .iter()
            .filter(|label| !localizer.has_message(label))
            .collect();
        assert!(missing.is_empty(), "missing {missing:?}");
        let untranslated: Vec<&&str> = labels
            .iter()
            .filter(|label| localizer.text(label) == **label)
            .collect();
        assert!(untranslated.is_empty(), "untranslated {untranslated:?}");
        for group in CommandGroup::ALL {
            assert!(localizer.has_message(group.label_id()));
        }
    }

    #[test]
    fn the_settings_override_beats_the_os_language() {
        assert_eq!(resolve_locale(Some("tr-TR"), "en-US"), "tr-TR");
        assert_eq!(resolve_locale(Some("  de "), "en-US"), "de");
        assert_eq!(resolve_locale(Some(""), "en-US"), "en-US");
        assert_eq!(resolve_locale(Some("   "), "fr-FR"), "fr-FR");
        assert_eq!(resolve_locale(None, "fr-FR"), "fr-FR");
    }

    #[test]
    fn unknown_locales_fall_back_to_english_text() {
        let english = localizer_for("en").text("cmd-file-save");
        let unknown = localizer_for("xx-YY");
        assert_eq!(unknown.loaded_locales(), ["en"]);
        assert_eq!(unknown.text("cmd-file-save"), english);
    }

    #[test]
    fn the_welcome_document_falls_back_to_english() {
        let english = welcome_text("en");
        assert!(english.starts_with("# "));
        assert_eq!(welcome_text("en-US"), english);
        assert_eq!(welcome_text("xx_YY"), english);
        assert_eq!(welcome_text(""), english);
    }

    #[test]
    fn every_welcome_file_on_disk_is_embedded() {
        let mut on_disk = BTreeSet::new();
        let files = std::fs::read_dir(assets_dir().join("welcome"))
            .unwrap()
            .map(|file| file.unwrap().path());
        for file in files.filter(|file| file.extension().is_some_and(|ext| ext == "md")) {
            on_disk.insert((
                file.file_stem().unwrap().to_string_lossy().into_owned(),
                std::fs::read_to_string(&file).unwrap(),
            ));
        }
        let embedded: BTreeSet<_> = embedded::WELCOME_FILES
            .iter()
            .map(|(name, text)| ((*name).to_owned(), (*text).to_owned()))
            .collect();
        assert_eq!(embedded, on_disk);
        assert!(embedded.iter().any(|(name, _)| name == "en"));
    }
}
